// Chart builders shared by the chart clips. FT-style: horizontal hairline grid, ink baseline, mono tick labels,
// direct labels at the data (no legend boxes). Ink is Dockhand, gray is the comparison, a dashed gray line is a
// projection. Every number comes from data.js (generated by render.ts from evals/results).
(() => {
  const NS = "http://www.w3.org/2000/svg";
  const f2 = (v) => v.toFixed(2);
  function el(tag, attrs, parent, text) {
    const e = document.createElementNS(NS, tag);
    for (const [k, v] of Object.entries(attrs)) e.setAttribute(k, String(v));
    if (text !== undefined) e.textContent = text;
    parent.appendChild(e);
    return e;
  }
  const usd = (v) => `$${v.toFixed(2)}`;

  /**
   * Cumulative cost, run by run. box: plot area {L, R, T, B} in px. Returns the groups to fade in, in order:
   * axes, cu (measured), dockhand, projection, labels.
   * opts.accent: "dockhand" puts the accent on Dockhand's total (once per frame).
   */
  function costChart(svg, box, data, opts = {}) {
    const C = data.cost;
    const N = C.totalRuns;
    const M = C.measuredCuRuns;
    const cu = [0, ...C.cuCum];
    const co = [0, ...C.compileCum];
    const yMax = opts.yMax ?? 12;
    const yStep = opts.yStep ?? 4;
    const X = (r) => box.L + (r / N) * (box.R - box.L);
    const Y = (v) => box.B - (v / yMax) * (box.B - box.T);
    const path = (s, a, b) => {
      let d = "";
      for (let i = a; i <= b; i++) d += `${i === a ? "M" : "L"}${f2(X(i))},${f2(Y(s[i]))}`;
      return d;
    };
    const g = (id) => el("g", { id }, svg);
    const axes = g("axes");
    for (let v = 0; v < yMax - 1e-9; v += yStep) {
      if (v > 0) el("line", { x1: box.L, x2: box.R, y1: Y(v), y2: Y(v), stroke: "#E3E1DB", "stroke-width": 2 }, axes);
      el("text", { x: box.L - 22, y: Y(v) + 13, "text-anchor": "end", class: "tick" }, axes, `$${v}`);
    }
    el("line", { x1: box.L, x2: box.R, y1: box.B, y2: box.B, stroke: "#6B6B6B", "stroke-width": 2 }, axes);
    const xt = opts.xTicks ?? [1, 25, 50, 75, N];
    for (const r of xt) {
      el("line", { x1: X(r), x2: X(r), y1: box.B, y2: box.B + 12, stroke: "#6B6B6B", "stroke-width": 2 }, axes);
      el("text", { x: X(r), y: box.B + 56, "text-anchor": "middle", class: "tick" }, axes, String(r));
    }
    el("text", { x: box.R, y: box.B + 112, "text-anchor": "end", class: "axis" }, axes, opts.xTitle ?? "Runs");

    const cuG = g("cuMeasured");
    el("path", { d: path(cu, 0, M), fill: "none", stroke: "#6B6B6B", "stroke-width": 5, "stroke-linejoin": "round", "stroke-linecap": "round" }, cuG);
    const proj = g("cuProjected");
    el("path", { d: path(cu, M, N), fill: "none", stroke: "#6B6B6B", "stroke-width": 5, "stroke-dasharray": "14 12", "stroke-linecap": "butt" }, proj);
    const dock = g("dockhand");
    el("path", { d: path(co, 0, N), fill: "none", stroke: "#111111", "stroke-width": 6, "stroke-linejoin": "round", "stroke-linecap": "round" }, dock);

    // Direct labels at the line ends.
    const cuLbl = g("cuLabel");
    const endCu = { x: X(N), y: Y(cu[N]) };
    el("circle", { cx: endCu.x, cy: endCu.y, r: 8, fill: "#6B6B6B" }, cuLbl);
    el("text", { x: endCu.x - 28, y: endCu.y - 106, "text-anchor": "end", class: "lbl gray" }, cuLbl, opts.cuName ?? "Computer use every run");
    el("text", { x: endCu.x - 28, y: endCu.y - 8, "text-anchor": "end", class: "val gray" }, cuLbl, usd(C.cuTotalUsd));
    const projLbl = g("projLabel");
    el("text", { x: endCu.x - 28, y: endCu.y - 62, "text-anchor": "end", class: "note" }, projLbl, `dashed: projected after run ${M}`);

    const dockLbl = g("dockLabel");
    const endCo = { x: X(N), y: Y(co[N]) };
    el("circle", { cx: endCo.x, cy: endCo.y, r: 8, fill: "#111111" }, dockLbl);
    el("text", { x: endCo.x - 24, y: endCo.y - 74, "text-anchor": "end", class: "lbl" }, dockLbl, opts.dockName ?? "Dockhand");
    el("text", { x: endCo.x - 24, y: endCo.y - 22, "text-anchor": "end", class: `val${opts.accent === "dockhand" ? " accent" : ""}` }, dockLbl, usd(C.compileTotalUsd));

    return { axes, cuG, dock, proj, cuLbl, projLbl, dockLbl, X, Y };
  }

  /**
   * Unit rows: one square per case, `handled` first, the rest outlined. rows: [{ label, qual, handled, cases,
   * ink, accent }]. Returns the row elements to fade in.
   */
  function unitRows(container, rows, o = {}) {
    const per = o.perLine ?? 21;
    const cell = o.cell ?? 28;
    const gap = o.gap ?? 6;
    const out = [];
    for (const r of rows) {
      const row = document.createElement("div");
      row.className = "urow";
      const head = document.createElement("div");
      head.className = "uhead";
      head.innerHTML = `<span class="uname">${r.label}${r.qual ? `<span class="gray">, ${r.qual}</span>` : ""}</span>`;
      row.appendChild(head);
      const body = document.createElement("div");
      body.className = "ubody";
      const grid = document.createElement("div");
      grid.className = "ugrid";
      grid.style.gridTemplateColumns = `repeat(${per}, ${cell}px)`;
      grid.style.gap = `${gap}px`;
      for (let i = 0; i < r.cases; i++) {
        const c = document.createElement("i");
        c.style.width = `${cell}px`;
        c.style.height = `${cell}px`;
        if (i < r.handled) c.style.background = r.ink ? "#111111" : "#6B6B6B";
        else c.style.boxShadow = "inset 0 0 0 2px #CFCCC4";
        grid.appendChild(c);
      }
      body.appendChild(grid);
      const fig = document.createElement("span");
      fig.className = `ufig mono${r.accent ? " accent" : ""}`;
      fig.textContent = `${r.handled}/${r.cases}`;
      body.appendChild(fig);
      row.appendChild(body);
      if (r.note) {
        const n = document.createElement("div");
        n.className = "unote";
        n.textContent = r.note;
        row.appendChild(n);
      }
      container.appendChild(row);
      out.push(row);
    }
    return out;
  }

  /** The three arms on the same 42 cases, from data.js (baseline section of live-headline.md). */
  function baselineRows(data, accent) {
    const b = data.baseline;
    return [
      { label: "Recorded script", qual: "one selector per step", ...b.scriptPrimary },
      { label: "Recorded script", qual: "as exported", ...b.script },
      { label: "Dockhand", qual: "heal ladder + read-back", ...b.dockhand, ink: true, accent },
    ];
  }

  window.DHC = { el, usd, costChart, unitRows, baselineRows };
})();
